\set ON_ERROR_STOP on
CREATE OR REPLACE FUNCTION fn_set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER trg_users_updated BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION fn_set_updated_at();
CREATE OR REPLACE FUNCTION fn_audit() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE rec JSONB; BEGIN rec:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END; INSERT INTO audit_log(table_name,record_id,action,old_data,new_data,changed_by) VALUES(TG_TABLE_NAME,(rec->>TG_ARGV[0])::BIGINT,TG_OP,CASE WHEN TG_OP IN('UPDATE','DELETE') THEN to_jsonb(OLD) END,CASE WHEN TG_OP IN('INSERT','UPDATE') THEN to_jsonb(NEW) END,NULLIF(current_setting('app.current_user_id',true),'')::BIGINT); RETURN NULL; END $$;
CREATE TRIGGER trg_bookings_audit AFTER INSERT OR UPDATE OR DELETE ON bookings FOR EACH ROW EXECUTE FUNCTION fn_audit('booking_id');
CREATE TRIGGER trg_vehicles_audit AFTER INSERT OR UPDATE OR DELETE ON vehicles FOR EACH ROW EXECUTE FUNCTION fn_audit('vehicle_id');
CREATE TRIGGER trg_rentals_audit AFTER INSERT OR UPDATE OR DELETE ON rentals FOR EACH ROW EXECUTE FUNCTION fn_audit('rental_id');
CREATE TRIGGER trg_payments_audit AFTER INSERT OR UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION fn_audit('payment_id');
CREATE TRIGGER trg_users_audit AFTER INSERT OR UPDATE OR DELETE ON users FOR EACH ROW EXECUTE FUNCTION fn_audit('user_id');
CREATE TRIGGER trg_damage_audit AFTER INSERT OR UPDATE OR DELETE ON damage_reports FOR EACH ROW EXECUTE FUNCTION fn_audit('report_id');
CREATE TRIGGER trg_reviews_audit AFTER INSERT OR UPDATE OR DELETE ON reviews FOR EACH ROW EXECUTE FUNCTION fn_audit('review_id');
CREATE OR REPLACE FUNCTION create_booking(p_customer_id BIGINT,p_vehicle_id BIGINT,p_start TIMESTAMPTZ,p_end TIMESTAMPTZ,p_pickup_branch INT,p_drop_branch INT,p_method payment_method,p_extra_ids INT[] DEFAULT '{}') RETURNS BIGINT LANGUAGE plpgsql AS $$ DECLARE v_rate NUMERIC(10,2); v_days INT; v_total NUMERIC(10,2); v_id BIGINT; v_extra NUMERIC(10,2); BEGIN
 IF p_end<=p_start THEN RAISE EXCEPTION 'End must be after start'; END IF; IF p_start<now()-INTERVAL '5 minutes' THEN RAISE EXCEPTION 'Start date is in the past'; END IF;
 IF NOT EXISTS(SELECT 1 FROM users u JOIN customer_profiles cp USING(user_id) WHERE u.user_id=p_customer_id AND u.role='customer' AND u.is_active AND cp.licence_expiry>=p_end::date) THEN RAISE EXCEPTION 'Customer not eligible: active account and valid licence required'; END IF;
 SELECT c.base_daily_rate INTO v_rate FROM vehicles v JOIN vehicle_categories c USING(category_id) WHERE v.vehicle_id=p_vehicle_id AND v.status='available' FOR UPDATE OF v; IF NOT FOUND THEN RAISE EXCEPTION 'Vehicle not available'; END IF;
 IF EXISTS(SELECT 1 FROM unnest(p_extra_ids) x LEFT JOIN extras e ON e.extra_id=x WHERE e.extra_id IS NULL) THEN RAISE EXCEPTION 'Unknown extra'; END IF;
 v_days:=GREATEST(1,CEIL(EXTRACT(EPOCH FROM(p_end-p_start))/86400)::INT); SELECT COALESCE(SUM(price_per_day),0) INTO v_extra FROM extras WHERE extra_id=ANY(p_extra_ids); v_total:=v_days*(v_rate+v_extra);
 INSERT INTO bookings(customer_id,vehicle_id,pickup_branch_id,drop_branch_id,period,daily_rate_snapshot,total_amount,status) VALUES(p_customer_id,p_vehicle_id,p_pickup_branch,p_drop_branch,tstzrange(p_start,p_end,'[)'),v_rate,v_total,'confirmed') RETURNING booking_id INTO v_id;
 INSERT INTO booking_extras SELECT v_id,e.extra_id,1,e.price_per_day FROM extras e WHERE e.extra_id=ANY(p_extra_ids);
 INSERT INTO payments(booking_id,amount,method,status,transaction_ref) VALUES(v_id,v_total,p_method,'paid','TXN-'||gen_random_uuid()); RETURN v_id;
 EXCEPTION WHEN exclusion_violation THEN RAISE EXCEPTION 'Vehicle is already booked for these dates'; END $$;
CREATE OR REPLACE FUNCTION cancel_booking(p_booking_id BIGINT,p_customer_id BIGINT) RETURNS NUMERIC LANGUAGE plpgsql AS $$ DECLARE b bookings%ROWTYPE; refund NUMERIC(10,2); pay_method payment_method; BEGIN SELECT * INTO b FROM bookings WHERE booking_id=p_booking_id AND customer_id=p_customer_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found'; END IF; IF b.status NOT IN('pending','confirmed') THEN RAISE EXCEPTION 'Cannot cancel a booking that is %',b.status; END IF; SELECT method INTO pay_method FROM payments WHERE booking_id=b.booking_id AND status='paid' ORDER BY paid_at LIMIT 1; IF pay_method IS NULL THEN RAISE EXCEPTION 'No successful payment to refund'; END IF; refund:=CASE WHEN lower(b.period)-now()>=interval '24 hours' THEN b.total_amount ELSE ROUND(b.total_amount*.5,2) END; UPDATE bookings SET status='cancelled' WHERE booking_id=b.booking_id; IF refund>0 THEN INSERT INTO payments(booking_id,amount,method,status,transaction_ref) VALUES(b.booking_id,refund,pay_method,'refunded','RFD-'||gen_random_uuid()); END IF; RETURN refund; END $$;
CREATE OR REPLACE FUNCTION fn_rental_status_sync() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE v_vehicle BIGINT; BEGIN IF TG_OP='INSERT' THEN UPDATE bookings SET status='active' WHERE booking_id=NEW.booking_id; SELECT vehicle_id INTO v_vehicle FROM bookings WHERE booking_id=NEW.booking_id; UPDATE vehicles SET status='rented' WHERE vehicle_id=v_vehicle AND status='available'; ELSIF NEW.return_at IS NOT NULL AND OLD.return_at IS NULL THEN UPDATE bookings SET status='completed' WHERE booking_id=NEW.booking_id; SELECT vehicle_id INTO v_vehicle FROM bookings WHERE booking_id=NEW.booking_id; UPDATE vehicles SET odometer_km=NEW.odometer_in,status='available' WHERE vehicle_id=v_vehicle AND status='rented'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trg_rental_sync AFTER INSERT OR UPDATE ON rentals FOR EACH ROW EXECUTE FUNCTION fn_rental_status_sync();
CREATE VIEW v_vehicle_catalog AS SELECT v.vehicle_id,v.reg_number,v.make,v.model,v.fuel,v.transmission,v.image_url,b.branch_id,b.city,c.name AS category,c.seats,c.base_daily_rate FROM vehicles v JOIN vehicle_categories c USING(category_id) JOIN branches b USING(branch_id) WHERE v.status='available';
CREATE OR REPLACE FUNCTION fn_available_vehicles(p_city TEXT,p_start TIMESTAMPTZ,p_end TIMESTAMPTZ) RETURNS SETOF v_vehicle_catalog LANGUAGE sql STABLE AS $$ SELECT vc.* FROM v_vehicle_catalog vc WHERE vc.city ILIKE p_city AND p_end>p_start AND NOT EXISTS(SELECT 1 FROM bookings bk WHERE bk.vehicle_id=vc.vehicle_id AND bk.status IN('pending','confirmed','active') AND bk.period && tstzrange(p_start,p_end,'[)')); $$;
CREATE MATERIALIZED VIEW mv_monthly_revenue AS SELECT date_trunc('month',paid_at) AS month,SUM(CASE status WHEN 'paid' THEN amount WHEN 'refunded' THEN -amount ELSE 0 END) AS net_revenue,COUNT(DISTINCT booking_id) AS bookings FROM payments GROUP BY 1;
CREATE UNIQUE INDEX ON mv_monthly_revenue(month);
